/**
 * Generate src/client/generated.ts: the palette for dsh's theme service and the favicon.
 *
 * GENERATED AT BUILD, NEVER TYPED BY HAND. A copy typed out is a copy that drifts, and drift here
 * means two palettes for one product. `check-dsh-tokens` guards the names in the source table
 * (dsh-bridge.css); the generated file inherits that guarantee.
 */
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'
import { generatePalette } from './palette.mjs'

const here = path.dirname(fileURLToPath(import.meta.url))
const root = path.resolve(here, '..')
const ui = path.resolve(root, '../../ui/tracy-ui/src')
const brand = path.resolve(root, '../../../docs/design/brand')
const out = path.join(root, 'src', 'client', 'generated.ts')

const palette = generatePalette(
  readFileSync(path.join(ui, 'tokens.css'), 'utf8'),
  readFileSync(path.join(ui, 'dsh-bridge.css'), 'utf8')
)

// The favicon rides along as a data URI: the plugin cannot serve files, and dsh's own
// favicon.svg is a static file of the web frontend that no plugin hook reaches.
const svg = readFileSync(path.join(brand, 'favicon', 'tracy-favicon.svg'), 'utf8')
  .replace(/\s+/g, ' ')
  .trim()
const favicon = `data:image/svg+xml;utf8,${encodeURIComponent(svg)}`

mkdirSync(path.dirname(out), { recursive: true })
writeFileSync(
  out,
  `/* GENERATED by scripts/gen-palette.mjs — do not edit.\n` +
    `   Sources: @tracy/ui/src/tokens.css + @tracy/ui/src/dsh-bridge.css, docs/design/brand/favicon. */\n` +
    `export const PALETTE: Record<string, { light: string; dark: string }> = ${JSON.stringify(palette, null, 2)}\n\n` +
    `export const FAVICON = ${JSON.stringify(favicon)}\n`
)
console.log(
  `tracy-brand: palette with ${Object.keys(palette).length} dsh tokens, favicon ${favicon.length} bytes`
)
